// Тест NEMA 17 с драйвером A4988 и ESP32

#define STEP_PIN 14   // Пин STEP на ESP32 (GPIO14)
#define DIR_PIN 12    // Пин DIR на ESP32 (GPIO12)
#define ENABLE_PIN 13 // Пин ENABLE на ESP32 (GPIO13)

void setup() {
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  pinMode(ENABLE_PIN, OUTPUT);

  digitalWrite(ENABLE_PIN, LOW);  // LOW = драйвер включен (активен)
  digitalWrite(DIR_PIN, HIGH);    // HIGH = вращение в одну сторону
}

void loop() {
  // Вращение в одном направлении (1 оборот = 200 шагов для NEMA17)
  digitalWrite(DIR_PIN, HIGH);  // Задаем направление
  for(int i = 0; i < 200; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(1000);    // Пауза между шагами (скорость)
    digitalWrite(STEP_PIN, LOW);
    delayMicroseconds(1000);
  }
  delay(2000);  // Пауза 2 секунды

  // Вращение в обратном направлении
  digitalWrite(DIR_PIN, LOW);
  for(int i = 0; i < 200; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(1000);
    digitalWrite(STEP_PIN, LOW);
    delayMicroseconds(1000);
  }
  delay(2000);
}
